module coherence_cmd_decode (
    input  logic [4:0] cmd,
    output logic       req_shared,
    output logic       req_exclusive,
    output logic       invalidate,
    output logic       illegal
);

    always_comb begin
        req_shared    = 1'b0;
        req_exclusive = 1'b0;
        invalidate    = 1'b0;
        illegal       = 1'b0;

        unique case (cmd)
            5'h00: req_shared    = 1'b1; // ReadShared
            5'h01: req_exclusive = 1'b1; // ReadExclusive
            5'h02: invalidate    = 1'b1; // Invalidate
            5'h03: begin                  // Upgrade
                req_exclusive = 1'b1;
                invalidate    = 1'b1;
            end
            5'h10, 5'h11: begin            // Probe responses
                // No action, metadata only
            end
            default: illegal = 1'b1;
        endcase
    end

endmodule
