module pcie_tlp_decoder (
    input  logic [7:0] tlp_type,
    output logic       is_mem,
    output logic       is_cfg,
    output logic       is_msg,
    output logic       unsupported
);

    always_comb begin
        is_mem      = 1'b0;
        is_cfg      = 1'b0;
        is_msg      = 1'b0;
        unsupported = 1'b0;

        casez (tlp_type)
            8'b0000_000?: is_mem = 1'b1; // MemRd/MemWr
            8'b0000_10??: is_cfg = 1'b1; // CfgRd/CfgWr
            8'b0011_0???: is_msg = 1'b1; // Messages
            default: unsupported = 1'b1;
        endcase
    end

endmodule
