module cdc_ctrl_fsm (
    input  logic clk,
    input  logic rst_n,
    input  logic req,
    input  logic ack,
    output logic req_sync
);

    typedef enum logic [1:0] {
        CDC_IDLE,
        CDC_REQ,
        CDC_WAIT_ACK,
        CDC_DONE
    } cdc_state_t;

    cdc_state_t state, next_state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= CDC_IDLE;
        else
            state <= next_state;
    end

    always_comb begin
        req_sync  = 1'b0;
        next_state = state;

        unique case (state)
            CDC_IDLE: begin
                if (req)
                    next_state = CDC_REQ;
            end

            CDC_REQ: begin
                req_sync = 1'b1;
                next_state = CDC_WAIT_ACK;
            end

            CDC_WAIT_ACK: begin
                req_sync = 1'b1;
                if (ack)
                    next_state = CDC_DONE;
            end

            CDC_DONE: begin
                if (!req)
                    next_state = CDC_IDLE;
            end

            default: next_state = CDC_IDLE;
        endcase
    end

endmodule
