module mem_burst_ctrl (
    input  logic [1:0] burst_type,
    output logic [3:0] burst_len,
    output logic       burst_wrap
);

    always_comb begin
        burst_len  = 4'd0;
        burst_wrap = 1'b0;

        unique case (burst_type)
            2'b00: burst_len = 4'd1;   // Fixed
            2'b01: burst_len = 4'd4;   // INCR4
            2'b10: burst_len = 4'd8;   // INCR8
            2'b11: begin               // WRAP
                burst_len  = 4'd4;
                burst_wrap = 1'b1;
            end
            default: ;
        endcase
    end

endmodule
