module cpu_full_decoder (
    input  logic [31:0] instr,
    output logic        reg_write,
    output logic        mem_read,
    output logic        mem_write,
    output logic        branch,
    output logic        illegal
);

    logic [6:0] opcode;
    logic [2:0] funct3;
    logic [1:0] addr_mode;

    assign opcode    = instr[6:0];
    assign funct3    = instr[14:12];
    assign addr_mode = instr[21:20];

    always_comb begin
        reg_write = 1'b0;
        mem_read  = 1'b0;
        mem_write = 1'b0;
        branch    = 1'b0;
        illegal   = 1'b0;

        unique case (opcode)

            7'b0110011: begin // ALU register ops
                reg_write = 1'b1;
                unique case (funct3)
                    3'b000, 3'b111, 3'b110: ; // ADD/AND/OR
                    default: illegal = 1'b1;
                endcase
            end

            7'b0000011: begin // LOAD
                mem_read  = 1'b1;
                reg_write = 1'b1;
                unique case (funct3)
                    3'b010: begin // LW
                        case (addr_mode)
                            2'b00, 2'b01: ; // direct/indexed
                            2'b10: illegal = 1'b1;
                            default: illegal = 1'b1;
                        endcase
                    end
                    default: illegal = 1'b1;
                endcase
            end

            7'b0100011: begin // STORE
                mem_write = 1'b1;
                unique case (funct3)
                    3'b010: begin // SW
                        case (addr_mode)
                            2'b00: ;        // direct
                            2'b01: ;        // indexed
                            default: illegal = 1'b1;
                        endcase
                    end
                    default: illegal = 1'b1;
                endcase
            end

            7'b1100011: begin // BRANCH
                branch = 1'b1;
                unique case (funct3)
                    3'b000, 3'b001: ; // BEQ/BNE
                    default: illegal = 1'b1;
                endcase
            end

            default: illegal = 1'b1;
        endcase
    end

endmodule
,"module cpu_full_decoder_assertions(

module packet_classifier (
    input  logic [31:0] hdr,
    output logic        fast_path,
    output logic        slow_path,
    output logic        drop
);

    logic [7:0] proto;
    logic [3:0] subtype;
    logic [2:0] qos;

    assign proto   = hdr[31:24];
    assign subtype = hdr[23:20];
    assign qos     = hdr[2:0];

    always_comb begin
        fast_path = 1'b0;
        slow_path = 1'b0;
        drop      = 1'b0;

        unique case (proto)
            8'h08: begin // IPv4
                case (subtype)
                    4'h0: begin // UDP
                        case (qos)
                            3'b000, 3'b001: fast_path = 1'b1;
                            3'b111: drop = 1'b1;
                            default: slow_path = 1'b1;
                        endcase
                    end

                    4'h1: begin // TCP
                        case (qos)
                            3'b000: fast_path = 1'b1;
                            default: slow_path = 1'b1;
                        endcase
                    end

                    default: slow_path = 1'b1;
                endcase
            end

            8'h86: begin // IPv6
                case (subtype)
                    4'h0, 4'h1: slow_path = 1'b1;
                    default: drop = 1'b1;
                endcase
            end

            default: drop = 1'b1;
        endcase
    end

endmodule
,"module packet_classifier_assertions(

module storage_cmd_proc (
    input  logic [7:0] cmd,
    input  logic [3:0] feature,
    input  logic [1:0] subop,
    output logic       exec,
    output logic       flush,
    output logic       error
);

    always_comb begin
        exec  = 1'b0;
        flush = 1'b0;
        error = 1'b0;

        unique case (cmd)
            8'h01: begin // READ
                case (feature)
                    4'h0, 4'h1: exec = 1'b1;
                    4'hF: begin
                        case (subop)
                            2'b00: exec = 1'b1;
                            default: error = 1'b1;
                        endcase
                    end
                    default: error = 1'b1;
                endcase
            end

            8'h02: begin // WRITE
                case (feature)
                    4'h0: exec = 1'b1;
                    4'hE: flush = 1'b1;
                    default: error = 1'b1;
                endcase
            end

            8'hFF: begin // FLUSH
                flush = 1'b1;
            end

            default: error = 1'b1;
        endcase
    end

endmodule
