module thermal_policy (
    input  logic [1:0] mode,
    input  logic [2:0] temp_level,
    output logic       throttle,
    output logic       shutdown
);

    always_comb begin
        throttle = 1'b0;
        shutdown = 1'b0;

        unique case (mode)
            2'b00: begin // Performance
                case (temp_level)
                    3'b000, 3'b001: ;
                    3'b010, 3'b011: throttle = 1'b1;
                    default: shutdown = 1'b1;
                endcase
            end

            2'b01: begin // Balanced
                case (temp_level)
                    3'b000: ;
                    3'b001, 3'b010: throttle = 1'b1;
                    default: shutdown = 1'b1;
                endcase
            end

            2'b10: begin // Power-save
                case (temp_level)
                    3'b000, 3'b001: throttle = 1'b1;
                    default: shutdown = 1'b1;
                endcase
            end

            default: shutdown = 1'b1;
        endcase
    end

endmodule
