module interconnect_router (
    input  logic [3:0] master_id,
    input  logic [1:0] txn_type,
    input  logic [1:0] burst,
    output logic       route_fast,
    output logic       route_slow,
    output logic       reject
);

    always_comb begin
        route_fast = 1'b0;
        route_slow = 1'b0;
        reject     = 1'b0;

        unique case (master_id)
            4'h0, 4'h1: begin
                case (txn_type)
                    2'b00: route_fast = 1'b1; // read
                    2'b01: begin              // write
                        case (burst)
                            2'b00, 2'b01: route_fast = 1'b1;
                            default: route_slow = 1'b1;
                        endcase
                    end
                    default: reject = 1'b1;
                endcase
            end

            4'hF: begin
                case (txn_type)
                    2'b00: route_slow = 1'b1;
                    default: reject = 1'b1;
                endcase
            end

            default: reject = 1'b1;
        endcase
    end

endmodule
