module obi_to_axil_resp (
    input  logic [1:0] obi_resp_i,
    output logic [1:0] axil_rresp_o,
    output logic [1:0] axil_bresp_o
);

    always_comb begin
        axil_rresp_o = 2'b00;
        axil_bresp_o = 2'b00;

        unique case (obi_resp_i)
            2'b00: begin
                axil_rresp_o = 2'b00;
                axil_bresp_o = 2'b00;
            end

            2'b10: begin
                axil_rresp_o = 2'b10;
                axil_bresp_o = 2'b10;
            end

            default: begin
                axil_rresp_o = 2'b11;
                axil_bresp_o = 2'b11;
            end
        endcase
    end

endmodule
