module axil_tl_obi_bridge (
    input  logic        awvalid_i,
    input  logic        arvalid_i,
    input  logic        wvalid_i,
    input  logic [31:0] awaddr_i,
    input  logic [2:0]  awprot_i,
    input  logic [2:0]  tl_opcode_i,
    input  logic [1:0]  obi_resp_i,
    output logic        tl_a_valid_o,
    output logic [2:0]  tl_a_opcode_o,
    output logic        obi_req_o,
    output logic        obi_we_o,
    output logic [1:0]  axil_rresp_o
);

    always_comb begin
        tl_a_valid_o   = 1'b0;
        tl_a_opcode_o  = 3'b000;
        obi_req_o      = 1'b0;
        obi_we_o       = 1'b0;
        axil_rresp_o   = 2'b00;

        // AXI ? TL
        unique case (1'b1)
            arvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b000; // Get
            end

            awvalid_i && wvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b001; // PutFull
            end

            default: ;
        endcase

        // TL ? OBI
        if (tl_a_valid_o) begin
            unique case (tl_a_opcode_o)
                3'b000: begin
                    obi_req_o = 1'b1;
                    obi_we_o  = 1'b0;
                end

                3'b001, 3'b010: begin
                    obi_req_o = 1'b1;
                    obi_we_o  = 1'b1;
                end

                default: ;
            endcase
        end

        // OBI ? AXI Response
        unique case (obi_resp_i)
            2'b00: axil_rresp_o = 2'b00; // OKAY
            2'b10: axil_rresp_o = 2'b10; // SLVERR
            default: axil_rresp_o = 2'b11; // DECERR
        endcase
    end

endmodule
,"module axil_tl_obi_bridge_assertions

module piton_l2_repl (
    input  logic [3:0] req_i,            // request from 4 cores
    input  logic [1:0] line_state_i [3:0], // MESI states per core
    input  logic [1:0] lru_i [3:0],     // LRU priority
    output logic [3:0] grant_o,
    output logic [3:0] evict_o,
    output logic [3:0] stall_o
);

    always_comb begin
        grant_o = 4'b0000;
        evict_o = 4'b0000;
        stall_o = 4'b0000;

        for (int i = 0; i < 4; i++) begin
            if (req_i[i]) begin
                unique case (line_state_i[i])
                    2'b00: grant_o[i] = 1'b1; // Invalid ? grant
                    2'b01: begin
                        unique case (lru_i[i])
                            2'b00: grant_o[i] = 1'b1;
                            2'b01: evict_o[i] = 1'b1;
                            default: stall_o[i] = 1'b1;
                        endcase
                    end
                    2'b10: begin
                        unique case (lru_i[i])
                            2'b00, 2'b01: grant_o[i] = 1'b1;
                            2'b10: evict_o[i] = 1'b1;
                            default: stall_o[i] = 1'b1;
                        endcase
                    end
                    2'b11: stall_o[i] = 1'b1;
                    default: stall_o[i] = 1'b1;
                endcase
            end
        end
    end
endmodule
,"module piton_l2_repl_assertions()

module chisel_event_dispatch (
    input  logic [7:0] evt_i,
    input  logic [3:0] fsm_state_i,
    output logic       fire_o,
    output logic       stall_o,
    output logic       error_o
);

    always_comb begin
        fire_o  = 1'b0;
        stall_o = 1'b0;
        error_o = 1'b0;

        unique case (fsm_state_i)
            4'd0: begin
                unique case (evt_i[1:0])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            4'd1: begin
                unique case (evt_i[3:2])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            4'd2: begin
                unique case (evt_i[5:4])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            4'd3: begin
                unique case (evt_i[7:6])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            default: error_o = 1'b1;
        endcase
    end
endmodule
