module multi_core_cache_arb (
    input  logic [3:0] req_i,
    input  logic [1:0] line_state_i [3:0],
    input  logic [2:0] msg_type_i [3:0],
    input  logic priv_i [3:0],
    output logic [3:0] grant_o,
    output logic [3:0] nack_o
);

    always_comb begin
        grant_o = 4'b0000;
        nack_o  = 4'b0000;

        for (int i=0; i<4; i++) begin
            if (req_i[i]) begin
                unique case (line_state_i[i])
                    2'b00: begin
                        unique case (msg_type_i[i])
                            3'b000: begin
                                unique case (priv_i[i])
                                    1'b1: grant_o[i] = 1'b1;
                                    default: nack_o[i] = 1'b1;
                                endcase
                            end
                            3'b001: grant_o[i] = 1'b1;
                            default: nack_o[i] = 1'b1;
                        endcase
                    end
                    2'b01: begin
                        unique case (msg_type_i[i])
                            3'b010: grant_o[i] = 1'b1;
                            default: nack_o[i] = 1'b1;
                        endcase
                    end
                    2'b10, 2'b11: nack_o[i] = 1'b1;
                    default: nack_o[i] = 1'b1;
                endcase
            end
        end
    end
endmodule
