                            end
                            default: nack_o[i] = 1'b1;
                        endcase
                    end
                    2'b01: begin
                        unique case (msg_type_i[i])
                            3'b010: grant_o[i] = 1'b1;
                            default: nack_o[i] = 1'b1;
                        endcase
                    end
                    2'b10, 2'b11: nack_o[i] = 1'b1;
                    default: nack_o[i] = 1'b1;
