module chisel_event_fsm (
    input  logic [7:0] evt_i,
    input  logic [3:0] state_i,
    output logic fire_o,
    output logic stall_o,
    output logic error_o
);

    always_comb begin
        fire_o  = 1'b0;
        stall_o = 1'b0;
        error_o = 1'b0;

        unique case (state_i)
            4'd0: unique case (evt_i[1:0])
                      2'b00: fire_o = 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            4'd1: unique case (evt_i[3:2])
                      2'b00: fire_o = 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            4'd2: unique case (evt_i[5:4])
                      2'b00: fire_o = 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            4'd3: unique case (evt_i[7:6])
                      2'b00: fire_o = 1'b1;
                      2'b01: stall_o = 1'b1;
                      default: error_o = 1'b1;
                  endcase
            default: error_o = 1'b1;
        endcase
    end
endmodule
