module tl_axi_obi_sec (
    input  logic tl_valid_i,
    input  logic [2:0] tl_opcode_i,
    input  logic axi_awvalid_i,
    input  logic axi_arvalid_i,
    input  logic [1:0] obi_resp_i,
    input  logic priv_i,
    output logic tl_a_valid_o,
    output logic [2:0] tl_a_opcode_o,
    output logic obi_req_o,
    output logic obi_we_o,
    output logic [1:0] axi_rresp_o
);

    always_comb begin
        tl_a_valid_o  = 1'b0;
        tl_a_opcode_o = 3'b000;
        obi_req_o     = 1'b0;
        obi_we_o      = 1'b0;
        axi_rresp_o   = 2'b00;

        if (tl_valid_i) begin
            unique case (tl_opcode_i)
                3'b000: begin
                    tl_a_valid_o  = 1'b1;
                    tl_a_opcode_o = 3'b000;
                    obi_req_o     = 1'b1;
                    obi_we_o      = 1'b0;
                end
                3'b001, 3'b010: begin
                    tl_a_valid_o  = 1'b1;
                    tl_a_opcode_o = tl_opcode_i;
                    obi_req_o     = 1'b1;
                    obi_we_o      = 1'b1;
                end
                default: axi_rresp_o = 2'b11;
            endcase
        end

        unique case (1'b1)
            axi_arvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b000;
            end
            axi_awvalid_i: begin
                tl_a_valid_o  = 1'b1;
                tl_a_opcode_o = 3'b001;
            end
        endcase

        unique case (obi_resp_i)
            2'b00: axi_rresp_o = 2'b00;
            2'b10: axi_rresp_o = 2'b10;
            default: axi_rresp_o = 2'b11;
        endcase

        if (!priv_i) begin
            tl_a_valid_o = 1'b0;
            obi_req_o    = 1'b0;
            axi_rresp_o  = 2'b10;
        end
    end
endmodule
,"module tl_axi_obi_sec_assertions(

module sec_lc_gate_alert (
    input  logic sec_req_i,
    input  logic [2:0] lc_state_i,
    input  logic [1:0] access_type_i,
    input  logic priv_i,
    input  logic alert_i,
    output logic allow_o,
    output logic violation_o
);

    always_comb begin
        allow_o     = 1'b0;
        violation_o = 1'b0;

        if (sec_req_i) begin
            unique case (lc_state_i)
                3'b000: unique case (access_type_i)
                            2'b00: unique case (priv_i)
                                        1'b1: allow_o = alert_i ? 1'b0 : 1'b1;
                                        default: violation_o = 1'b1;
                                    endcase
                            2'b01: violation_o = 1'b1;
                            default: violation_o = 1'b1;
                        endcase
                3'b001: unique case (access_type_i)
                            2'b00, 2'b01: unique case (priv_i)
                                              1'b1: allow_o = alert_i ? 1'b0 : 1'b1;
                                              default: violation_o = 1'b1;
                                          endcase
                            default: violation_o = 1'b1;
                        endcase
                3'b010: unique case (access_type_i)
                            2'b01: unique case (priv_i)
                                      1'b1: allow_o = alert_i ? 1'b0 : 1'b1;
                                      default: violation_o = 1'b1;
                                  endcase
                            default: violation_o = 1'b1;
                        endcase
                default: violation_o = 1'b1;
            endcase
        end
    end
endmodule
