module sec_lc_gate_priv_mask (
    input  logic sec_req_i,
    input  logic [2:0] lc_state_i,
    input  logic [1:0] access_type_i,
    input  logic priv_i,
    input  logic mask_i,
    output logic allow_o,
    output logic violation_o
);

    always_comb begin
        allow_o = 1'b0;
        violation_o = 1'b0;

        if (sec_req_i) begin
            unique case (lc_state_i)
                3'b000: allow_o = (access_type_i==2'b00 && priv_i && !mask_i);
                3'b001: allow_o = ((access_type_i==2'b00 || access_type_i==2'b01) && priv_i && !mask_i);
                3'b010: allow_o = (access_type_i==2'b01 && priv_i && !mask_i);
                default: violation_o = 1'b1;
            endcase
        end
    end
endmodule
